import{TASKS02,EXERCISES02,auditRows,assess02,checkExercise02,copy,describeError02 as humanError}from'./legality02.mjs';import{board}from'../lessons/02/teaching/visuals.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function lab02Page({code,task,quizBlock=''}){return`<main id="main" class="wrap focused-lesson"><header class="focused-hero"><div class="breadcrumbs"><a href="../../index.html">课程</a> / Lab 02</div><h1>这张布局，真的放得下吗？</h1><p class="lead">从越界、重叠和漏放出发，学会检查整张布局，并解释每一次修改为什么有效。</p><nav class="focused-nav" aria-label="本课学习路径"><a href="#video">01 互动教学</a><a href="#lab">02 综合 Lab · Python</a><a href="#quiz">03 课后习题</a></nav></header><section id="video" class="focused-section"><span id="film"></span><span class="eyebrow">01 / LEARN</span><h2>互动讲解</h2><p class="small">先看一遍，也可以随时暂停，点图里的模块试一试。</p><iframe id="interactive-teaching-frame" title="Lab2互动教学" src="teaching/?embed=1&v=legality-1" allow="autoplay; fullscreen" scrolling="no" style="width:100%;height:850px;border:0;display:block"></iframe></section>
<section id="lab" class="focused-section"><span class="eyebrow">02 / EXPERIMENT</span><h2>找出问题，修好它，再造一个反例</h2><p>这三项任务分别检查诊断、修复和反例构造。尺寸和可移动的模块以每题规则为准。</p><label>选择任务 <select id="lab02-task">${TASKS02.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><p id="lab02-prompt"></p><button id="lab02-reset">重置当前任务</button><div id="lab02-board" class="lab02-board"></div><div id="lab02-table"></div><div id="lab02-controls"><label>选中模块 <select id="lab02-selected"></select></label> <button data-lab02-move="-1,0" aria-label="向左移动">←</button> <button data-lab02-move="0,1" aria-label="向上移动">↑</button> <button data-lab02-move="0,-1" aria-label="向下移动">↓</button> <button data-lab02-move="1,0" aria-label="向右移动">→</button> <button id="lab02-undo">撤销</button></div><p id="lab02-status" role="status"></p><div id="lab02-evidence"></div><label class="wide">写下你的理由<textarea id="lab02-explanation" rows="3"></textarea></label><div><button id="lab02-check" class="primary">检查并保存</button> <button id="lab02-hint">需要一点提示</button></div><p id="lab02-result" role="status"></p>
<article id="python" class="python-integrated"><h3>Python Lab：写一个完整布局检查器</h3><p>${esc(task.prompt.zh)}</p><details><summary>输入、返回值和错误码</summary><p>输入已经解析成五项记录，名称为字符串；outline和catalog的格式有效。你要检查rows中的实际数值、名称和几何。只要求有限数值与正尺寸，这个通用函数允许小数坐标。硬模块尺寸必须与catalog完全一致，禁止旋转。</p><p>errors为排序去重字符串：missing:B、duplicate:A、unknown:F、number:A、shape:A、outside:E、overlap:A/D。数值无效的行不参与形状、边界和交集计算；未知名称仍需检查有效数值、边界及与其它有效行的交集。</p><p>overlaps包含每一对有正面积交集的行，格式为{'ids':['A','D'],'area':1}；名称按字母排序，记录按(ids,area)排序。合法必须返回真正的True且errors为空；有任意错误时legal为False。完整报告不能遇到第一处错误就返回。</p><p>${task.tests.length}项检查只是基线。请自己再写一个能排除错误算法的例子，并解释为什么原来的测试没覆盖它。</p></details><textarea id="python-source" class="python-editor" aria-label="Python source code" spellcheck="false">${esc(code)}</textarea><div class="python-toolbar"><button id="python-run" class="primary">运行综合检查</button><button id="python-stop" disabled>停止</button><button id="python-reset">恢复模板</button></div><pre id="python-output" class="python-output" role="status">尚未检查。修改代码后，需要重新运行。</pre></article></section>
<section id="quiz" class="focused-section"><span class="eyebrow">03 / EXPLAIN</span><h2>课后练习：把判断的依据说清楚</h2><p>除了数值，也写下推理。做完后可以对照参考要点检查。</p>${EXERCISES02.map(q=>`<article class="extended-exercise" data-exercise02="${q.id}"><h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><div class="exercise-fields">${q.fields.map(([key,label])=>`<label>${esc(label)} <input type="number" step="any" data-field="${key}"></label>`).join('')}</div><label>你的推理<textarea data-explain rows="3"></textarea></label><button data-check>检查并保存</button> <button data-reveal>查看参考要点</button><p data-result role="status"></p><p data-rubric hidden>${esc(q.rubric)}</p></article>`).join('')}${quizBlock}</section></main>`;}
export function bindLab02({progress,save}){let task=TASKS02[0],rows=copy(task.rows),selected=0,history=[],edited=false,hint=false;progress.lab02Submissions=progress.lab02Submissions||{};progress.exercises02=progress.exercises02||{};const $=s=>document.querySelector(s),root=$('#lab02-board');
 function render(){const activeRow=root.contains(document.activeElement)?document.activeElement.closest('[data-row]')?.getAttribute('data-row'):null;const r=auditRows(rows,task.outline,task.catalog);root.innerHTML=`<svg viewBox="0 0 960 540" role="group" aria-label="布局实验网格"><defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${board(rows,task.outline,{x:90,y:60,w:780,h:415,corners:task.id==='cross'})}</svg>`;$('#lab02-prompt').textContent=task.prompt;$('#lab02-table').innerHTML=`<table><thead><tr><th>行</th><th>模块</th><th>x</th><th>y</th><th>宽×高</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r[0])}${task.movable&&!task.movable.includes(r[0])?'（固定）':''}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}×${r[4]}</td></tr>`).join('')}</tbody></table>`;$('#lab02-selected').innerHTML=rows.map((r,i)=>`<option value="${i}" ${task.movable&&!task.movable.includes(r[0])?'disabled':''} ${i===selected?'selected':''}>${esc(r[0])}（第${i+1}行）</option>`).join('');$('#lab02-controls').hidden=task.id==='diagnose';$('#lab02-undo').disabled=!history.length;$('#lab02-status').textContent=task.id==='diagnose'?'先对照清单找齐全部错误，再提交你的判断。':r.legal?'当前布局没有名称、尺寸、边界或重叠错误。':'当前问题：'+r.errors.map(humanError).join('，');if(activeRow!=null)root.querySelector('[data-row="'+activeRow+'"]')?.focus({preventScroll:true});}
 function load(id){clearDrag();task=TASKS02.find(t=>t.id===id);rows=copy(task.rows);selected=Math.max(0,rows.findIndex(r=>task.movable?.includes(r[0])));history=[];edited=false;hint=false;$('#lab02-result').textContent='';$('#lab02-explanation').value=progress.lab02Submissions[task.id]?.explanation||'';$('#lab02-evidence').innerHTML=task.id==='diagnose'?`<fieldset><legend>你找到了哪些错误？</legend>${task.options.map(code=>`<label><input type="checkbox" value="${esc(code)}" data-error-code> ${esc(humanError(code))}</label>`).join('')}</fieldset>`:task.id==='repair'?`<div class="exercise-fields"><label>起始A/D交叠面积 <input id="lab02-overlapA" type="number" step="any"></label><label>起始B/D交叠面积 <input id="lab02-overlapB" type="number" step="any"></label><label>起始E右边缘 <input id="lab02-rightE" type="number" step="any"></label></div>`:`<label>当前交叠面积 <input id="lab02-area" type="number" step="any"></label>`;render();}
 function move(dx,dy){if(!task.movable?.includes(rows[selected][0])){render();$('#lab02-result').textContent='这块在本题中固定不动。';return;}history.push(copy(rows));rows[selected][1]+=dx;rows[selected][2]+=dy;edited=true;$('#lab02-result').textContent='';render();}
 $('#lab02-task').onchange=e=>load(e.target.value);$('#lab02-reset').onclick=()=>load(task.id);$('#lab02-selected').onchange=e=>selected=Number(e.target.value);for(const b of document.querySelectorAll('[data-lab02-move]'))b.onclick=()=>move(...b.dataset.lab02Move.split(',').map(Number));$('#lab02-undo').onclick=()=>{if(history.length){rows=history.pop();edited=true;render();}};
 root.onkeydown=e=>{const r=e.target.closest('[data-row]');if(!r)return;selected=Number(r.dataset.row);const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,1],ArrowDown:[0,-1]}[e.key];if(d){e.preventDefault();move(...d);}};
 let drag;function clearDrag(){if(!drag)return;const saved=drag;drag=null;rows=copy(saved.rows);try{if(root.hasPointerCapture(saved.pointerId))root.releasePointerCapture(saved.pointerId);}catch{}}root.onpointerdown=e=>{const r=e.target.closest('[data-row]');if(!r)return;selected=Number(r.dataset.row);if(!task.movable?.includes(rows[selected][0])){render();$('#lab02-result').textContent='这块在本题中固定不动。';root.querySelector('[data-row="'+selected+'"]')?.focus({preventScroll:true});return;}const svg=root.querySelector('svg'),p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());drag={rows:copy(rows),p,unit:Number(svg.querySelector('[data-board]').dataset.unit),selected,pointerId:e.pointerId};r.focus({preventScroll:true});root.setPointerCapture(e.pointerId);e.preventDefault();};root.onpointermove=e=>{if(!drag)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(root.querySelector('svg').getScreenCTM().inverse());rows=copy(drag.rows);rows[drag.selected][1]+=Math.round((p.x-drag.p.x)/drag.unit);rows[drag.selected][2]-=Math.round((p.y-drag.p.y)/drag.unit);render();};root.onpointerup=()=>{const saved=drag;drag=null;if(saved&&JSON.stringify(rows)!==JSON.stringify(saved.rows)){history.push(saved.rows);edited=true;}if(saved)try{root.releasePointerCapture(saved.pointerId);}catch{}render();};root.onpointercancel=()=>{clearDrag();render();};
 $('#lab02-hint').onclick=()=>{hint=true;$('#lab02-result').textContent=task.hint;};$('#lab02-check').onclick=()=>{const evidence={codes:[...document.querySelectorAll('[data-error-code]:checked')].map(e=>e.value)};for(const key of['overlapA','overlapB','rightE','area'])evidence[key]=$('#lab02-'+key)?.value;const result=assess02(task.id,rows,evidence),explanation=$('#lab02-explanation').value;if(task.id!=='diagnose'&&!edited)result.errors.unshift('先实际修改布局，再检查你的结果。');const numeric=result.ok&&(task.id==='diagnose'||edited);progress.lab02Submissions[task.id]={version:1,rows:copy(rows),evidence,numericPassed:numeric,explanation,hintUsed:hint,explanationStatus:'submitted-not-graded'};save();$('#lab02-result').textContent=result.errors.length?result.errors.join('\n'):explanation.trim().length<30?'条件与数值符合要求，请再写清楚你的理由。':'条件与数值符合要求。解释已保存，请对照题目确认推理是否完整。';};
 for(const article of document.querySelectorAll('[data-exercise02]')){const id=article.dataset.exercise02,saved=progress.exercises02[id]||{};for(const input of article.querySelectorAll('[data-field]'))input.value=saved.values?.[input.dataset.field]??'';article.querySelector('[data-explain]').value=saved.explanation||'';let revealed=!!saved.revealed;article.querySelector('[data-check]').onclick=()=>{const values=Object.fromEntries([...article.querySelectorAll('[data-field]')].map(e=>[e.dataset.field,e.value])),explanation=article.querySelector('[data-explain]').value,ok=checkExercise02(id,values);progress.exercises02[id]={values,explanation,numericPassed:ok,revealed,explanationStatus:'submitted-not-graded'};save();article.querySelector('[data-result]').textContent=!ok?'数值还不对，再检查一下边界和共同区间。':explanation.trim().length<30?'数值通过，请补上你的推理。':'数值通过，解释已保存。请按参考要点检查理由。'+(revealed?'（已查看参考）':'');};article.querySelector('[data-reveal]').onclick=()=>{revealed=true;article.querySelector('[data-rubric]').hidden=false;progress.exercises02[id]={...(progress.exercises02[id]||{}),revealed:true};save();article.querySelector('[data-result]').textContent='参考要点已显示，请比较自己的推理；不计作独立完成。';};}
 load(task.id);
}
